-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 3
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 3 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 03', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 03 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-03.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é um arquivo STL e como ele descreve a superfície do objeto.', 0.3, 'STL é um formato de arquivo que descreve a superfície do objeto como uma malha de triângulos.', 'Nota cheia: diz que é um formato de arquivo e que a superfície é descrita por uma malha de triângulos. Metade: só um dos dois. Zero: definição errada ou em branco.'),
      (v_atividade, 1, 2, 'Diga se a afirmação do colega sobre a cor e sobre a unidade está correta e justifique.', 0.3, 'A afirmação está errada: o STL não guarda cor nem unidade; só a forma da superfície. A cor azul não vai junto e a escala precisa ser conferida no fatiador.', 'Nota cheia: diz que está errada e aponta que o STL não guarda cor nem unidade. Metade: aponta só a cor ou só a unidade. Zero: diz que está correta.'),
      (v_atividade, 1, 3, 'Explique como o grupo deve conferir a escala do chaveiro depois de abrir o STL no fatiador.', 0.4, 'Conferir no fatiador as medidas do chaveiro (comprimento, largura e altura) com as que foram modeladas no Tinkercad e ajustar a escala se estiverem diferentes, pois o STL não traz a unidade.', 'Nota cheia: diz que a conferência é feita no fatiador comparando as medidas com o modelo. Metade: fala em conferir medidas, mas sem dizer onde ou com o que comparar. Zero: sem relação.'),
      (v_atividade, 2, 1, 'Descreva como exportar o chaveiro em STL no Tinkercad (botão e formato escolhidos).', 0.3, 'Clicar no botão Exportar do Tinkercad e escolher o formato .STL.', 'Nota cheia: cita o botão Exportar e o formato .STL. Metade: cita só um deles. Zero: nenhum ou formato errado.'),
      (v_atividade, 2, 2, 'Cite três conferências que o grupo deve fazer antes de exportar, relacionando-as com a situação descrita.', 0.4, 'Conferir as medidas do chaveiro; conferir que a peça está apoiada no plano de trabalho (no caso, abaixá-la até o plano); conferir que não há formas soltas (apagar a forma de teste que sobrou).', 'Nota cheia: as três conferências, ligadas à situação (plano de trabalho e forma solta). Metade: duas conferências. Zero: uma ou nenhuma.'),
      (v_atividade, 2, 3, 'Explique por que se deve exportar somente a peça final, agrupada.', 0.3, 'Porque o arquivo deve conter só o objeto que será impresso; formas soltas ou separadas iriam junto para o fatiador e seriam impressas ou atrapalhariam. Agrupada, a peça final vira um único corpo.', 'Nota cheia: explica que só o objeto final deve ir no arquivo e que o agrupamento reúne a peça. Metade: explica só um dos dois. Zero: sem relação.'),
      (v_atividade, 3, 1, 'Explique o que o fatiador faz com o arquivo STL e o que ele entrega para a impressora.', 0.4, 'O fatiador transforma o STL em G-code, dividindo o modelo em camadas e dando à impressora as instruções de movimento e de impressão.', 'Nota cheia: cita a transformação do STL em G-code e a ideia de camadas ou instruções para a impressora. Metade: cita só um desses pontos. Zero: sem relação.'),
      (v_atividade, 3, 2, 'Cite dois exemplos de fatiador.', 0.2, 'Cura e PrusaSlicer.', 'Nota cheia: dois fatiadores corretos. Metade: um correto. Zero: nenhum correto.'),
      (v_atividade, 3, 3, 'Liste três parâmetros que podem ser configurados no fatiador.', 0.4, 'Três entre: altura de camada, preenchimento, temperatura do bico, temperatura da mesa, velocidade, paredes (perímetros).', 'Nota cheia: três parâmetros corretos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 4, 1, 'Explique o efeito de diminuir a altura de camada de 0,2 mm para 0,1 mm na qualidade da superfície.', 0.3, 'Camada mais fina (0,1 mm) deixa a superfície mais lisa e com melhor qualidade; com 0,2 mm a superfície fica menos refinada.', 'Nota cheia: diz que a camada mais fina dá melhor qualidade de superfície. Metade: resposta vaga, sem relacionar à superfície. Zero: relação invertida ou sem relação.'),
      (v_atividade, 4, 2, 'Explique o efeito dessa mudança no tempo de impressão.', 0.3, 'Camada mais fina aumenta o tempo de impressão, pois são necessárias mais camadas; passar de 0,2 mm para 0,1 mm deixa a impressão mais lenta.', 'Nota cheia: diz que o tempo aumenta e explica pela maior quantidade de camadas. Metade: diz só que aumenta. Zero: relação invertida ou sem relação.'),
      (v_atividade, 4, 3, 'Recomende uma altura de camada para o chaveiro com pouco tempo de máquina e justifique.', 0.4, 'Recomendar 0,2 mm (ou até mais grossa), porque gasta menos tempo e atende ao chaveiro, que não exige acabamento muito fino; a camada de 0,1 mm só vale se a qualidade for mais importante que o tempo.', 'Nota cheia: escolhe uma camada coerente com o pouco tempo e justifica pelo tempo. Metade: escolhe a camada coerente sem justificar. Zero: escolha incoerente com o pouco tempo e sem justificativa.'),
      (v_atividade, 5, 1, 'Explique o que o preenchimento controla na peça.', 0.3, 'O preenchimento controla a resistência da peça por dentro e a quantidade de material gasto.', 'Nota cheia: cita resistência e material gasto. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 5, 2, 'Explique o efeito de aumentar o preenchimento de 15% para 40% no material gasto e no peso do chaveiro.', 0.3, 'Com 40% há mais material dentro da peça: gasta mais filamento e o chaveiro fica mais pesado do que com 15%.', 'Nota cheia: diz que gasta mais material e fica mais pesado. Metade: diz só um dos dois. Zero: relação invertida ou sem relação.'),
      (v_atividade, 5, 3, 'Escolha entre 15% e 40% para esse chaveiro decorativo e justifique.', 0.4, 'Escolher 15%, porque o chaveiro é decorativo, não sofre grande esforço, e assim economiza material e deixa a peça mais leve (a faixa típica é de 15% a 20%).', 'Nota cheia: escolhe 15% e justifica por economia, leveza ou pouco esforço. Metade: escolhe 15% sem justificar. Zero: escolhe 40% sem justificativa coerente.'),
      (v_atividade, 6, 1, 'Explique para que serve a temperatura do bico e informe a faixa típica para PLA.', 0.3, 'A temperatura do bico controla a fluidez do plástico; para PLA, de 200 °C a 210 °C.', 'Nota cheia: cita a fluidez do plástico e a faixa aproximada. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 6, 2, 'Explique para que serve a temperatura da mesa e informe a faixa típica para PLA.', 0.3, 'A temperatura da mesa ajuda na aderência da primeira camada; para PLA, de 55 °C a 60 °C.', 'Nota cheia: cita a aderência da primeira camada e a faixa aproximada. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 6, 3, 'Proponha duas ações para melhorar a aderência da primeira camada nessa situação.', 0.4, 'Conferir/ajustar a temperatura da mesa para a faixa de 55 °C a 60 °C e usar uma borda (brim) para aumentar a área presa à mesa; também vale conferir se a peça está com a maior face plana apoiada na mesa.', 'Nota cheia: duas ações coerentes (temperatura da mesa, brim ou orientação com face plana). Metade: uma ação coerente. Zero: nenhuma coerente.'),
      (v_atividade, 7, 1, 'Explique a relação entre velocidade de impressão, tempo e qualidade, e indique a faixa típica de velocidade.', 0.3, 'Velocidade maior reduz o tempo, mas piora a qualidade; velocidade menor melhora a qualidade e leva mais tempo (relação tempo × qualidade). Faixa típica: 40 a 60 mm/s; 120 mm/s está muito acima.', 'Nota cheia: explica a relação tempo × qualidade e indica a faixa. Metade: só um deles. Zero: relação invertida ou sem relação.'),
      (v_atividade, 7, 2, 'Explique o que são as paredes (perímetros) e indique quantas voltas são típicas.', 0.3, 'As paredes (perímetros) são as voltas de plástico que contornam a peça e dão a resistência externa; o típico é de 2 a 3 voltas, então uma volta é pouco.', 'Nota cheia: define as paredes como voltas do contorno ligadas à resistência externa e indica 2 a 3 voltas. Metade: só um. Zero: sem relação.'),
      (v_atividade, 7, 3, 'Informe a espessura mínima de parede para uma peça comum e para uma peça que sofre esforço, e explique de onde vem o valor mínimo.', 0.4, 'Peça comum: pelo menos cerca de 0,8 mm, que é o dobro do diâmetro do bico de 0,4 mm. Peça que sofre esforço: 1,2 mm ou mais.', 'Nota cheia: os dois valores e a origem do valor mínimo (dobro do diâmetro do bico). Metade: os dois valores sem a origem, ou um valor com a origem. Zero: valores errados ou em branco.'),
      (v_atividade, 8, 1, 'Explique qual orientação deve ser usada em relação à maior face plana da peça.', 0.3, 'Imprimir com a maior face plana apoiada sobre a mesa; não deixar a peça em pé sobre uma ponta pequena.', 'Nota cheia: diz maior face plana sobre a mesa e rejeita a posição em pé na ponta. Metade: diz só a regra, sem aplicar à situação. Zero: orientação errada.'),
      (v_atividade, 8, 2, 'Explique por que as camadas são mais fracas entre si do que ao longo delas.', 0.3, 'A peça é construída em camadas empilhadas; a ligação entre uma camada e outra é mais fraca do que o plástico ao longo da própria camada, então a peça rompe mais facilmente entre as camadas.', 'Nota cheia: explica a construção por camadas e a ligação mais fraca entre elas. Metade: afirma que é mais fraca entre camadas, sem explicar. Zero: relação invertida ou sem relação.'),
      (v_atividade, 8, 3, 'Explique como essa característica deve ser considerada para a parte do chaveiro que recebe puxões.', 0.4, 'Orientar a peça de modo que o puxão aconteça ao longo das camadas e não tente separar uma camada da outra; assim a argola do chaveiro resiste mais e não se parte entre camadas.', 'Nota cheia: relaciona a direção do esforço com as camadas e propõe orientar para não separar as camadas. Metade: só diz que a orientação importa para a resistência. Zero: sem relação.'),
      (v_atividade, 9, 1, 'Explique o que são suportes e quando eles são necessários.', 0.3, 'Suportes são estruturas provisórias que sustentam partes suspensas; são necessários quando a inclinação passa de cerca de 45°.', 'Nota cheia: define como estrutura provisória para partes suspensas e cita a inclinação de cerca de 45°. Metade: só um. Zero: sem relação.'),
      (v_atividade, 9, 2, 'Cite duas desvantagens do uso de suportes.', 0.3, 'Deixam marcas na peça e gastam material (e tempo).', 'Nota cheia: duas desvantagens corretas. Metade: uma. Zero: nenhuma.'),
      (v_atividade, 9, 3, 'Proponha como evitar os suportes nessa peça e o que ajudaria uma peça com pouca base a ficar presa à mesa.', 0.4, 'Reorientar a peça (por exemplo, deitar a aba para que não fique suspensa) pode evitar os suportes; para peças com pouca base, uma borda (brim) ajuda na aderência.', 'Nota cheia: cita reorientar a peça e a borda (brim). Metade: cita um deles. Zero: nenhum.'),
      (v_atividade, 10, 1, 'Explique o que o grupo deve anotar do fatiador em cada configuração para montar a tabela.', 0.3, 'Anotar o tempo de impressão estimado e os gramas de filamento estimados de cada configuração, junto com os parâmetros usados.', 'Nota cheia: cita tempo e gramas de filamento por configuração. Metade: cita só um. Zero: sem relação.'),
      (v_atividade, 10, 2, 'Explique o que muda de uma configuração para outra e o que se espera encontrar em tempo e material.', 0.3, 'Muda a altura de camada (0,2 mm para 0,1 mm) ou o preenchimento (15% para 40%). Espera-se que a camada de 0,1 mm aumente o tempo e melhore a qualidade, e que o preenchimento de 40% gaste mais material e deixe a peça mais pesada e mais resistente.', 'Nota cheia: identifica o que muda e o efeito esperado em tempo ou material. Metade: só um dos dois. Zero: sem relação ou efeito invertido.'),
      (v_atividade, 10, 3, 'Escreva a recomendação final, com a configuração escolhida e a justificativa pelo equilíbrio entre qualidade e tempo.', 0.4, 'Resposta pessoal coerente: por exemplo, escolher 0,2 mm com 15%, por ser a combinação mais rápida e econômica que ainda atende ao chaveiro, ou justificar outra escolha pelo equilíbrio entre qualidade, tempo e material.', 'Nota cheia: escolhe uma das três configurações e justifica pelo equilíbrio entre qualidade e tempo. Metade: escolhe sem justificar o equilíbrio. Zero: sem escolha ou sem relação.');
end $$;
